// Audit metadata is generated by the server, never accepted from client payloads.
// Avoid storing task titles, notes, checklist contents, or other user-entered text.
public sealed class TaskActivity
{
    public long Id { get; set; }
    public string UserId { get; set; } = "";
    public int TaskId { get; set; }
    public string Kind { get; set; } = "";
    public DateTime OccurredAt { get; set; } = DateTime.UtcNow;
}

public static class TaskActivityKinds
{
    public const string Created = "created";
    public const string Edited = "edited";
    public const string Completed = "completed";
    public const string Reopened = "reopened";
    public const string Rescheduled = "rescheduled";

    public static void Record(TaskDbContext db, string userId, int taskId, string kind)
    {
        db.TaskActivities.Add(new TaskActivity {
            UserId = userId, TaskId = taskId, Kind = kind, OccurredAt = DateTime.UtcNow
        });
    }
}
